-- Skema SQLite untuk pengembangan lokal dan uji (nama kolom sama dengan schema.sql PostgreSQL)
CREATE TABLE admin (id INTEGER PRIMARY KEY, password_hash TEXT);
INSERT INTO admin (id) VALUES (1);
CREATE TABLE dokter (id INTEGER PRIMARY KEY AUTOINCREMENT, nama TEXT NOT NULL, spesialis TEXT NOT NULL, tarif INTEGER NOT NULL, hari TEXT NOT NULL DEFAULT '1,2,3,4,5', password_hash TEXT);
CREATE TABLE staf (id INTEGER PRIMARY KEY AUTOINCREMENT, nama TEXT NOT NULL, peran TEXT NOT NULL, password_hash TEXT);
CREATE TABLE pasien (id INTEGER PRIMARY KEY AUTOINCREMENT, nik TEXT NOT NULL UNIQUE, nama TEXT NOT NULL, tgl_lahir TEXT NOT NULL, gol_darah TEXT NOT NULL DEFAULT 'O', hp TEXT NOT NULL DEFAULT '', alamat TEXT NOT NULL DEFAULT '', alergi TEXT NOT NULL DEFAULT '', password_hash TEXT NOT NULL, setuju_privasi_pada TEXT, versi_privasi TEXT NOT NULL DEFAULT '', kode_pulih_hash TEXT);
CREATE TABLE obat (id INTEGER PRIMARY KEY AUTOINCREMENT, nama TEXT NOT NULL, stok INTEGER NOT NULL DEFAULT 0, harga INTEGER NOT NULL, stok_min INTEGER NOT NULL DEFAULT 20, kedaluwarsa TEXT);
CREATE TABLE stok_masuk (id INTEGER PRIMARY KEY AUTOINCREMENT, obat_id INTEGER NOT NULL REFERENCES obat(id) ON DELETE CASCADE, jumlah INTEGER NOT NULL, tanggal TEXT NOT NULL, catatan TEXT NOT NULL DEFAULT '', oleh TEXT NOT NULL DEFAULT '');
CREATE TABLE antrian (id INTEGER PRIMARY KEY AUTOINCREMENT, pasien_id INTEGER NOT NULL REFERENCES pasien(id), dokter_id INTEGER NOT NULL REFERENCES dokter(id), tanggal TEXT NOT NULL, no_antrian TEXT NOT NULL, keluhan TEXT NOT NULL, prioritas TEXT NOT NULL DEFAULT 'Normal', status TEXT NOT NULL DEFAULT 'Menunggu', dipanggil_pada TEXT);
CREATE TABLE rekam_medis (id INTEGER PRIMARY KEY AUTOINCREMENT, antrian_id INTEGER NOT NULL UNIQUE REFERENCES antrian(id), pasien_id INTEGER NOT NULL REFERENCES pasien(id), dokter_id INTEGER NOT NULL REFERENCES dokter(id), tanggal TEXT NOT NULL, tekanan_darah TEXT NOT NULL DEFAULT '', suhu REAL, bb REAL, tb REAL, icd TEXT NOT NULL DEFAULT '', diagnosis TEXT NOT NULL, tindakan TEXT NOT NULL DEFAULT '', sakit_hari INTEGER NOT NULL DEFAULT 0, rujukan TEXT NOT NULL DEFAULT '', resep_status TEXT NOT NULL DEFAULT 'Tanpa obat');
CREATE TABLE resep (id INTEGER PRIMARY KEY AUTOINCREMENT, rekam_id INTEGER NOT NULL REFERENCES rekam_medis(id) ON DELETE CASCADE, obat_id INTEGER NOT NULL REFERENCES obat(id), jumlah INTEGER NOT NULL);
CREATE TABLE tagihan (id INTEGER PRIMARY KEY AUTOINCREMENT, antrian_id INTEGER NOT NULL UNIQUE REFERENCES antrian(id), pasien_id INTEGER NOT NULL REFERENCES pasien(id), tanggal TEXT NOT NULL, tarif INTEGER NOT NULL, obat_total INTEGER NOT NULL DEFAULT 0, metode TEXT, total INTEGER NOT NULL DEFAULT 0, lunas INTEGER NOT NULL DEFAULT 0, tgl_bayar TEXT);
CREATE TABLE audit (id INTEGER PRIMARY KEY AUTOINCREMENT, waktu TEXT NOT NULL, oleh TEXT NOT NULL, peran TEXT NOT NULL, aksi TEXT NOT NULL, objek TEXT NOT NULL, objek_id INTEGER NOT NULL, rincian TEXT NOT NULL DEFAULT '');
CREATE TABLE push_sub (id INTEGER PRIMARY KEY AUTOINCREMENT, pasien_id INTEGER NOT NULL REFERENCES pasien(id) ON DELETE CASCADE, endpoint TEXT NOT NULL UNIQUE, p256dh TEXT NOT NULL, auth TEXT NOT NULL, dibuat TEXT NOT NULL);
CREATE TABLE login_gagal (id INTEGER PRIMARY KEY AUTOINCREMENT, ip TEXT NOT NULL, waktu TEXT NOT NULL);
